    {
      "section": "V1",
      "lyrics": [
        "水明かり 新芽に跳ねれば",
        "君は少し 早歩き",
        "夜中の食べこぼしは 夢の地図",
        "新しい朝がくる"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "風が通る 風が運ぶ",
        "ぼくらはわたげのように",
        "街にまかれ それぞれに"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "さよならペンギン",
        "てくてく歩いて笑ってよ",
        "世界に恋して まばたきを",
        "風が通る 風が運ぶ",
        "なみだがおちた",
        "さよならペンギン"
      ]
    }
  ],
  "section": "B1",
  "phrases": [
    {
      "id": "B1-01",
      "ja": "風が通る 風が運ぶ",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        6,
        6
      ]
    },
    {
      "id": "B1-02",
      "ja": "ぼくらはわたげのように",
      "budget": {
        "min": 10,
        "max": 10
      },
      "pattern": [
        4,
        6
      ]
    },
    {
      "id": "B1-03",
      "ja": "街にまかれ それぞれに",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": [
        6,
        5
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风穿行而过 风轻轻搬运"
        },
        {
          "id": "B1-02",
          "zh": "我们就像那蒲公英"
        },
        {
          "id": "B1-03",
          "zh": "散落街巷中 各自飘零"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风穿城而过 风带着梦"
        },
        {
          "id": "B1-02",
          "zh": "我们像蒲公英飘散"
        },
        {
          "id": "B1-03",
          "zh": "落在街角 各自生根"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风穿过这房间 风带走你和我"
        },
        {
          "id": "B1-02",
          "zh": "我们就像 蒲公英的绒毛"
        },
        {
          "id": "B1-03",
          "zh": "散落在城市里 各自去发芽"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风穿街巷 风载着光"
        },
        {
          "id": "B1-02",
          "zh": "我们像那飘散的绒毛"
        },
        {
          "id": "B1-03",
          "zh": "撒向城市 各落一方"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风穿过这长街 风带走些什么"
        },
        {
          "id": "B1-02",
          "zh": "我们就像 蒲公英的绒毛"
        },
        {
          "id": "B1-03",
          "zh": "被吹散在街口 各自去远方"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风儿穿行 风儿传送"
        },
        {
          "id": "B1-02",
          "zh": "我们如蒲公英绒"
        },
        {
          "id": "B1-03",
          "zh": "散落城中 各自飘零"
        }
      ]
    }
  ]
}

